const $ = (s) => document.querySelector(s);
const esc = (s) => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money = n => 'Rs ' + Number(n).toLocaleString('en-IN');
const people = [
  {id:'asha',name:'Asha Demo',initials:'AD',title:'Relationship Manager',team:'Client relationships',gross:50000,deductions:3200,login:'09:06',attendance:'Checked in 09:12',color:''},
  {id:'nikhil',name:'Nikhil Demo',initials:'ND',title:'Operations Executive',team:'Operations',gross:45000,deductions:2800,login:null,attendance:'Approved leave',color:'lilac'},
  {id:'riya',name:'Riya Demo',initials:'RD',title:'Relationship Manager',team:'Client relationships',gross:55000,deductions:3500,login:'08:58',attendance:'Check-in missing',color:'sand'}
];
const modules = [
  {id:'payroll',number:'01',title:'Payroll',text:'Salary components, maker-checker review and employee payslips.',screens:['payroll'],video:'01-payroll.mp4',refs:'R135-001 to 005, 018 to 020',question:'Confirm salary components, payroll cutoffs, final approver and historical import scope.'},
  {id:'attendance',number:'02',title:'Attendance & leave',text:'A day-by-day calendar, leave applications and regularization approvals.',screens:['attendance','leave','regularization'],video:'02-attendance-leave.mp4',refs:'R135-006 to 013, 022, 023, 026',question:'Confirm leave types, full/half-day eligibility, working hours, holidays and correction deadlines.'},
  {id:'people',number:'03',title:'Employee hub',text:'Organization structure, login-today indicators, profiles, documents and policies.',screens:['people','profile','policies'],video:'03-employee-hub.mp4',refs:'R135-014 to 017, 025 + latest scope',question:'Confirm document visibility, retention, policy upload rights and who maintains reporting lines.'},
  {id:'whatsapp',number:'04',title:'WhatsApp',text:'Operational conversations, templates and honest delivery tracking.',screens:['whatsapp'],video:'04-whatsapp.mp4',refs:'R135-060 to 064',question:'Confirm the approved business number, triggers, template wording, owners and retry policy.'},
  {id:'performance',number:'05',title:'Performance & appraisals',text:'Explainable scores, salary what-if, peer feedback and a structured review cycle.',screens:['performance','appraisals'],video:'05-performance-appraisals.mp4',refs:'R135-072 to 078',question:'Supply the approved workbook, score weights, peer-feedback rules, salary formula and review chain.'},
  {id:'controls',number:'06',title:'Activity & task controls',text:'Mandatory descriptions and senior-only task edits with reasons and history.',screens:['controls'],video:'06-activity-task-controls.mp4',refs:'R135-040 to 042, 049 + latest scope',question:'Confirm which senior roles may edit and who checks revisions. Processed instructions stay locked.'}
];
const routes={home:'Preview collection',payroll:'Payroll',attendance:'Attendance calendar',leave:'Leave management',regularization:'Regularization',people:'Organization',profile:'Employee profile',policies:'HR policies',whatsapp:'WhatsApp workspace',performance:'Performance',appraisals:'Appraisals',controls:'Activity & task controls',videos:'Video walkthroughs'};
const state={role:'hr',payroll:'Draft',day:3,month:8,year:2026,leave:[],corrections:[{id:1,date:'2026-09-03',from:'09:15',to:'18:00',reason:'Client visit in the morning; check-in was missed.',status:'Pending'}],checkedIn:false,checkinSource:'Laptop / office',profile:'asha',docs:{},ack:{},chat:'open',messages:[],delivery:'Failed: temporary connection',period:'month',scoreRole:'rm',salary:55000,appraisal:'Self-review draft',selfText:'',goalText:'Improve handoff completeness with a weekly checklist review.',managerText:'',activity:[],taskAmount:25000,taskPending:null,taskHistory:[],policyYear:'2026',feedbackStorageError:false};
let route='home',toastTimer,returnFocus;
const avatar=p=>`<span class="avatar ${p.color||''}" aria-hidden="true">${p.initials}</span>`;
const person=p=>`<div class="person">${avatar(p)}<div><strong>${p.name}</strong><small>${p.title}</small></div></div>`;
const badge=(text,type='')=>`<span class="badge ${type}">${text}</span>`;
const btn=(text,action,primary=false,extra='')=>`<button type="button" ${action?`data-action="${action}"`:''} class="${primary?'primary':''}" ${extra}>${text}</button>`;
const link=(text,r,primary=false)=>`<a class="button ${primary?'primary':''}" href="#${r}">${text}</a>`;
const card=(title,body,sub='')=>`<section class="card"><div class="card-head"><div><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}</div></div>${body}</section>`;
const stat=(label,value,note='',type='')=>`<div class="card stat ${type}"><span class="stat-label">${label}</span><div class="stat-value">${value}</div><small>${note}</small></div>`;
const notice=(title,text,type='')=>`<div class="notice ${type}"><strong>${title}</strong><p>${text}</p></div>`;
const head=(eyebrow,title,desc,actions='')=>`<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${desc}</p></div><div class="actions">${actions}</div></div>`;
const tabs=names=>`<div class="tabs">${names.map(r=>`<a href="#${r}" class="${route===r?'active':''}">${routes[r]}</a>`).join('')}</div>`;
const moneyLine=(label,n,total=false)=>`<div class="line ${total?'total':''}"><span>${label}</span><span class="money">${money(n)}</span></div>`;
function table(headers,rows){return `<div class="table-scroll"><table><thead><tr>${headers.map(h=>`<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function showToast(text){clearTimeout(toastTimer);$('#toast').textContent=text;$('#toast').hidden=false;toastTimer=setTimeout(()=>$('#toast').hidden=true,4500);}
function dialog(title,body){returnFocus=document.activeElement;$('#dialog-content').innerHTML=`<h2 id="dialog-title">${title}</h2>${body}`;$('#dialog').showModal();}
function closeDialog(){$('#dialog').close();returnFocus?.focus();}
function download(name,text,type='text/plain;charset=utf-8'){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([text],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function groupFor(r){return modules.find(m=>m.screens.includes(r)) || {id:'general',title:'Overall preview',question:'Tell us what to keep, change or clarify in the mock screens.'};}
function home(){return head('FOCUSED DESIGN REVIEW','People first. Clearer daily work.','A separate preview for each requested area. Explore the screens, watch the walkthroughs and tell us what needs to change.',link('Watch the walkthroughs','videos',true))+
  `<section class="hero"><div><div class="eyebrow">YOUR NEXT PHASE / SIX FOCUSED PREVIEWS</div><h1>A connected employee experience, ready to review.</h1><p>From attendance and payroll to conversations and performance. Everything here is a working simulation, not a change to the live platform.</p></div><div class="hero-label"><strong>6</strong><span>module walkthroughs</span></div></section>`+
  `<div class="grid cols-3">${modules.map(m=>`<section class="card module-card"><span class="number">${m.number} / PREVIEW</span><h2>${m.title}</h2><p>${m.text}</p><div class="coverage">${m.refs}</div><div class="actions">${link('Explore screens',m.id,true)}${link('Watch video','videos/'+m.id)}</div></section>`).join('')}</div>`+
  notice('Review scope only','NSE order placement, broader dashboards, imports and other tracker work are outside this prototype. Source references remain unchanged. Current mock scope follows your latest instructions.');}
function payroll(){const employee=state.role==='employee',rows=employee?[people[0]]:people;const totalGross=rows.reduce((n,p)=>n+p.gross,0),totalDed=rows.reduce((n,p)=>n+p.deductions,0);return head('HR / MONTHLY PAYROLL',employee?'My payslips':'A calmer payroll close.','August 2026 sample run. Attendance is reconciled before preparation; a separate senior checks the run.',badge(state.payroll,state.payroll==='Finalized'?'':'amber'))+
  `<div class="grid cols-3">${stat(employee?'My gross salary':'Gross salaries',money(totalGross),'Illustrative August data')}${stat('Deductions',money(totalDed),'Example amounts, not statutory rates')}${stat('Net payable',money(totalGross-totalDed),'No bank payment is initiated','accent')}</div>`+
  `<div class="grid split spacer">${card(employee?'My payroll record':'Payroll run / AUG-2026',`<div class="stepper"><div class="done"><strong>01 Prepared</strong>HR manager</div><div class="${state.payroll!=='Draft'?'done':''}"><strong>02 Review</strong>Senior approver</div><div class="${state.payroll==='Finalized'?'done':''}"><strong>03 Finalized</strong>Read-only snapshot</div></div>`+table(['Employee','Gross','Deductions','Net pay','Details'],rows.map(p=>[person(p),money(p.gross),money(p.deductions),`<strong>${money(p.gross-p.deductions)}</strong>`,btn('Breakdown','salary',false,`data-id="${p.id}"`)]))+`<div class="actions spacer">${!employee&&state.role==='hr'&&state.payroll==='Draft'?btn('Submit mock run for review','payroll-submit',true):''}${!employee&&state.role==='senior'&&state.payroll==='In review'?btn('Finalize mock payroll','payroll-finalize',true)+btn('Return for correction','payroll-return'):''}${btn('View sample payslip','payslip')}${state.payroll==='Finalized'?btn('Download sample payslip','payslip-download'):''}</div>`)}
  ${card('Review checklist',`<div class="line"><span>Salary structure</span>${badge('3 reviewed')}</div><div class="line"><span>Attendance reconciliation</span>${badge('August locked')}</div><div class="line"><span>Pending August corrections</span>${badge('None')}</div><div class="line"><span>Prepared by</span><strong>Maya Demo / HR</strong></div><div class="line"><span>Final authority</span><strong>Kiran Demo / Senior</strong></div>`+notice('Two different responsibilities','Switch the preview role above to try the maker and checker. These are simulated UI permissions, not a security implementation.')+`<p class="subtle">Company formulas, tax inputs, cutoff dates, bank export and Zoho history must be confirmed before building the real payroll engine.</p>`)}</div>`;}
function attendanceStatus(day){const date=`${state.year}-${String(state.month+1).padStart(2,'0')}-${String(day).padStart(2,'0')}`;if(state.leave.some(r=>r.status==='Approved'&&date>=r.from&&date<=r.to))return 'Leave';if(state.month!==8||state.year!==2026)return 'No data';if(day>5)return 'Upcoming';if(state.corrections.some(r=>r.date===date&&r.status==='Approved'))return 'Present';if(state.corrections.some(r=>r.date===date&&r.status==='Pending'))return 'Correction';if(day===4)return 'Leave';if(day===5)return state.checkedIn?'Present':'Not checked in';return 'Present';}
function leaveUsed(type){return state.leave.filter(r=>r.status==='Approved'&&r.type===type).reduce((n,r)=>n+(r.duration==='half'?.5:Math.round((Date.parse(r.to)-Date.parse(r.from))/86400000)+1),0);}
function attendance(){const first=new Date(Date.UTC(state.year,state.month,1)).getUTCDay(),days=new Date(Date.UTC(state.year,state.month+1,0)).getUTCDate();const monthName=new Date(Date.UTC(state.year,state.month,1)).toLocaleString('en',{month:'long',timeZone:'UTC'});const dayState=attendanceStatus(state.day);return head('HR / ATTENDANCE','Every day, in one place.','Review attendance, approved leave and pending corrections without confusing app login with check-in.',btn('Preview check-in','checkin',true))+tabs(['attendance','leave','regularization'])+
  `<div class="grid cols-4">${stat('Employee','Asha Demo','My calendar / sample data')}${stat('Logged in today','09:06','App access only; not attendance')}${stat('Today’s attendance',state.checkedIn?'Present':'Not recorded',state.checkedIn?'Mock check-in recorded':'Check-in still required',state.checkedIn?'accent':'')}${stat('Pending corrections',String(state.corrections.filter(r=>r.status==='Pending').length),'Awaiting senior review','purple')}</div>`+
  `<div class="grid split spacer">${card('Attendance calendar',`<div class="calendar-toolbar">${btn('Previous month','month-prev')}<h2>${monthName} ${state.year}</h2>${btn('Next month','month-next')}</div><div class="calendar">${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(d=>`<div class="weekday">${d}</div>`).join('')}${'<div class="day blank"></div>'.repeat(first)}${Array.from({length:days},(_,i)=>{const d=i+1,status=attendanceStatus(d),type=status==='Present'?'present':status==='Leave'?'leave':status==='Correction'?'pending':'weekend';return `<button class="day ${d===5&&state.month===8?'today':''} ${d===state.day?'selected':''}" data-action="day" data-id="${d}" aria-label="${d} ${monthName}, ${status}"><strong>${d}</strong><span class="${type}">${status}</span></button>`;}).join('')}</div><div class="legend"><span><i style="background:#92b888"></i>Present</span><span><i style="background:#ada0d0"></i>Approved leave</span><span><i style="background:#dcb862"></i>Correction pending</span><span>No data is not an absence</span></div>`)}
  ${card(`${state.day} ${monthName} / Day details`,`${badge(dayState,dayState==='Correction'?'amber':dayState==='Leave'?'lilac':'')}<div class="spacer"><div class="line"><span>Employee</span><strong>Asha Demo</strong></div><div class="line"><span>Check-in</span><strong>${dayState==='Present'?'09:15':'Not recorded'}</strong></div><div class="line"><span>Check-out</span><strong>${dayState==='Present'&&state.day<5?'18:00':'Not recorded'}</strong></div><div class="line"><span>Source</span><strong>${dayState==='Present'?(state.day===5?esc(state.checkinSource):'Laptop / office'):'Not available'}</strong></div></div>`+notice('Corrections are not automatic','A pending correction changes the calendar only after approval. Corrections after payroll closes need a controlled adjustment, not a silent rewrite.','amber')+link('Request a correction','regularization',true)+`<p class="subtle spacer">Working hours, lunch treatment, office-network restrictions and field-work exceptions are awaiting your policy.</p>`)}</div>`;}
function leave(){return head('HR / LEAVE','Plan time away, with clarity.','Balances, leave applications and decisions stay connected to the attendance calendar.')+tabs(['attendance','leave','regularization'])+
  `<div class="grid cols-3">${stat('Casual leave',(6-leaveUsed('Casual leave'))+' days','Illustrative balance, not company entitlement','accent')}${stat('Privilege leave',(9-leaveUsed('Privilege leave'))+' days','Half-day availability needs confirmation')}${stat('Requests awaiting review',state.leave.filter(r=>r.status==='Pending').length,'No deduction before approval')}</div><div class="grid cols-2 spacer">${card('Apply for leave',`<form id="leave-form" novalidate><div class="form-grid"><label>Leave type<select name="type"><option>Casual leave</option><option>Privilege leave</option></select></label><label>Duration<select name="duration"><option value="full">Full day</option><option value="half">Half day (policy to confirm)</option></select></label><label>From date<input name="from" type="date" value="2026-09-10"></label><label>To date<input name="to" type="date" value="2026-09-10"></label><label class="full">Reason<textarea name="reason" placeholder="Explain your request"></textarea></label></div><p id="leave-error" class="error" role="alert"></p><button class="primary" type="submit">Submit mock leave request</button></form>`+notice('Policy assumption for review','Casual leave is full-day only in this example. All entitlements, exceptions and special leave categories require written confirmation.','amber'))}${card('My requests',`<div class="request"><div class="actions"><strong>4 September</strong>${badge('Approved','lilac')}</div><p>Privilege leave / 1 day</p><small class="muted">Visible on the attendance calendar.</small></div>${state.leave.map(r=>`<div class="request"><div class="actions"><strong>${esc(r.from)} to ${esc(r.to)}</strong>${badge(r.status,r.status==='Pending'?'amber':'')}</div><p>${esc(r.type)} / ${esc(r.duration)} day<br>${esc(r.reason)}</p>${r.status==='Pending'&&state.role==='senior'?btn('Approve mock leave','leave-approve',true,`data-id="${r.id}"`)+btn('Reject','leave-reject',false,`data-id="${r.id}"`):''}</div>`).join('')}`)}</div>`;}
function regularization(){return head('HR / REGULARIZATION','Correct a record. Keep the history.','A correction is requested by the employee, checked by a senior and then reflected in attendance.')+tabs(['attendance','leave','regularization'])+
  `<div class="grid cols-2">${card('Attendance correction',`<form id="correction-form" novalidate><div class="form-grid"><label class="full">Correction type<select id="correction-kind" name="kind"><option value="attendance">Correct attendance times</option><option value="leave">Convert absence to leave</option></select></label><label id="correction-leave-label" class="full" hidden>Leave type<select name="leaveType"><option>Casual leave</option><option>Privilege leave</option></select></label><label class="full">Date<input name="date" type="date" value="2026-09-02"></label><label>Correct check-in<input name="from" type="time" value="09:15"></label><label>Correct check-out<input name="to" type="time" value="18:00"></label><label class="full">Reason <span aria-hidden="true">*</span><textarea name="reason" placeholder="Explain why the record needs correcting"></textarea></label></div><p id="correction-error" class="error" role="alert"></p><button class="primary">Submit mock correction</button></form>`)}${card('Approval queue',state.corrections.map(r=>`<div class="request"><div class="actions"><strong>${esc(r.date)}</strong>${badge(r.status,r.status==='Pending'?'amber':'')}</div><p>Asha Demo / ${r.kind==='leave'?esc(r.leaveType)+' / full day':r.from+' to '+r.to}<br>${esc(r.reason)}</p><small class="muted">Original record preserved. Reviewer: Kiran Demo.</small><div class="actions">${r.status==='Pending'&&state.role==='senior'?btn('Approve correction','correction-approve',true,`data-id="${r.id}"`)+btn('Reject correction','correction-reject',false,`data-id="${r.id}"`):r.status==='Pending'?'<span class="subtle">Switch to Senior approver to review.</span>':link('View calendar','attendance')}</div></div>`).join('')+notice('Closed payroll is protected','This sample correction belongs to September. It does not rewrite the finalized August run. A later payroll adjustment needs an agreed process.'))}</div>`;}
function organization(){return head('HR / EMPLOYEE HUB','See the team. Find your person.','The organization chart is visible to all employees. App-login indicators are not attendance or live-online indicators.',link('My employee profile','profile',true))+tabs(['people','profile','policies'])+
  `<div class="grid cols-3">${stat('Team members','5','Fictional organization')}${stat('Logged in today','4 of 5','Mock snapshot: 5 Sep, 10:00 IST','accent')}${stat('Reporting structure','3 teams','HR permissions are separate from CRM roles')}</div><section class="card org-tree spacer"><div class="card org-leader">${avatar({initials:'KD',color:'sand'})}<h3>Kiran Demo</h3><p class="subtle">Business head / Senior approver</p><div class="presence"><span class="dot"></span>Logged in today, 08:45</div></div><div class="grid cols-3">${['Client relationships','Operations','People operations'].map((team,i)=>`<section class="org-team"><h3>${team}</h3>${(i===2?[{id:'maya',name:'Maya Demo',initials:'MD',title:'HR Manager',login:'09:00',attendance:'Checked in',color:'lilac'}]:people.filter(p=>p.team===team)).map(p=>`<article class="person-card">${person(p)}<div class="presence ${p.login?'':'off'}"><span class="dot"></span>${p.login?'Logged in today, '+p.login:'Not logged in today'}</div><p class="subtle">${p.id==='maya'?'Reports to Kiran Demo':'Reports to Kiran Demo'}</p>${p.id!=='maya'?`<button class="small-button spacer" data-action="profile" data-id="${p.id}">View profile</button>`:''}</article>`).join('')}</section>`).join('')}</div></section>`+notice('Visible team structure does not mean visible personnel files','Colleagues see work details and login-today status. Salary, résumé, PAN, Aadhaar and private personnel data are limited to self and authorized HR in the proposed design.');}
function profile(){const p=people.find(p=>p.id===state.profile)||people[0],privateAccess=state.role==='hr'||(state.role==='employee'&&p.id==='asha');return head('HR / EMPLOYEE PROFILE','A complete record, carefully shared.','Sample personnel information only. Do not upload real identity documents to this public prototype.')+tabs(['people','profile','policies'])+
  `<section class="card"><div class="profile-top"><span class="avatar large ${p.color}">${p.initials}</span><div><div class="eyebrow">EMPLOYEE / DEMO-${p.id.toUpperCase()}</div><h2>${p.name}</h2><div class="profile-meta"><span>${p.title}</span><span>${p.team}</span><span>Reports to Kiran Demo</span></div></div></div></section><div class="grid cols-2 spacer">${card('Work profile',`<div class="line"><span>Joining date</span><strong>1 April 2025 / sample</strong></div><div class="line"><span>Work location</span><strong>Pune office</strong></div><div class="line"><span>CRM role</span><strong>${p.title}</strong></div><div class="line"><span>HR role</span><strong>Employee self-service</strong></div><div class="line"><span>Logged in today</span><strong>${p.login?`Yes, ${p.login} IST`:'Not yet'}</strong></div>`+notice('Separate signals',`${p.attendance}. A login does not prove a full day of attendance.`))}${card('Personnel documents',privateAccess?['Resume','PAN card','Aadhaar card','Profile photo','Asset handover'].map((name,i)=>`<div class="document"><span class="file-icon">${i===3?'IMG':'PDF'}</span><div class="file-copy"><strong>${name}</strong><small>${state.docs[p.id+name]?'Sample updated / v2':'Fictional placeholder / v1'} · Self + HR only</small></div>${btn('Preview','document',false,`data-id="${esc(name)}"`)}${btn('Use sample','document-update',false,`data-id="${esc(name)}"`)}</div>`).join(''):`<div class="empty"><h3>Personnel files are private</h3><p class="spacer">This preview role can see work details, but not this employee's personnel documents.</p></div>`)}</div>${privateAccess?card('Private profile details',`<div class="grid cols-3"><div><div class="section-label">Personal contact</div><strong>demo@example.invalid</strong><p class="subtle">Phone: not provided in this mock</p></div><div><div class="section-label">Work experience</div><strong>3 years / illustrative</strong><p class="subtle">Previous employment details</p></div><div><div class="section-label">Nominee details</div><strong>Sample nominee</strong><p class="subtle">Relationship and declaration to confirm</p></div></div>`):''}`;}
function policies(){return head('HR / POLICIES','One place for the company handbook.','Current policies and historical versions are available to every employee.',`<label>Policy year<select id="policy-year"><option ${state.policyYear==='2026'?'selected':''}>2026</option><option ${state.policyYear==='2025'?'selected':''}>2025</option></select></label>`)+tabs(['people','profile','policies'])+
  `<div class="grid cols-3">${['Attendance & leave','Employee handbook','Holiday calendar'].map((name,i)=>`<section class="card policy"><span class="file-icon">PDF</span><div>${badge(state.policyYear==='2026'?'Current sample':'Archived sample',state.policyYear==='2025'?'gray':'')}<h2 class="spacer">${name}</h2></div><p>${['Check-in, leave categories and correction process. Company rules still need approval.','Conduct, reporting, work arrangements and employee responsibilities.','A year-specific company holiday list. No statutory calendar is assumed.'][i]}</p><div class="subtle">${state.policyYear} / Version ${state.policyYear==='2026'?'2':'1'} / Fictional policy</div><div class="actions">${btn('Read sample','policy-view',true,`data-id="${name}"`)}${state.ack[name+state.policyYear]?badge('Acknowledged'):btn('Acknowledge sample','policy-ack',false,`data-id="${name}"`)}</div></section>`).join('')}</div>`+notice('Historical versions stay available','Publishing a new policy must not overwrite an old PDF. Acknowledgement is shown as a proposed workflow, not an existing agreed legal acceptance.')+(state.role==='hr'?`<div class="actions spacer">${btn('Preview policy publishing','policy-publish')}</div>`:'');}
function whatsapp(){const selected=state.chat,closed=selected==='closed',blocked=selected==='optout';return head('COMMUNICATION / WHATSAPP','The right message. A visible outcome.','Operational follow-ups and conversations in one workspace. Every send below is simulated.',badge('Business number not connected','amber'))+
  `<div class="grid cols-4">${stat('Queued','12','Sample operational reminders')}${stat('Delivered','28','Provider delivery status, not acceptance','accent')}${stat('Needs attention','3','Failure reason stays visible','purple')}${stat('Opt-outs','1','Blocked from new messages')}</div><section class="card chat-layout spacer"><aside class="inbox"><h3>Conversations</h3>${[['open','Demo Client A','Service window open'],['closed','Demo Client B','Template required'],['optout','Demo Client C','Opted out']].map(([id,name,label])=>`<button data-action="chat-select" data-id="${id}" class="conversation ${id===selected?'active':''}"><strong>${name}</strong><small>${label}</small></button>`).join('')}</aside><div class="chat-main"><div class="card-head"><div><h2>Demo Client ${selected==='open'?'A':closed?'B':'C'}</h2><p>Owner: Asha Demo / Task reference DEMO-1042</p></div>${badge(blocked?'Opted out':closed?'Window closed':'Window open',blocked?'red':closed?'amber':'')}</div><div class="chat-bubbles"><div class="bubble">${blocked?'Please stop sending me messages.':closed?'Can you confirm my onboarding status?':'Could you please share the status of my request?'}<small>${closed?'Last inbound: over 24 hours ago':'Sample inbound message'}</small></div>${state.messages.filter(m=>m.chat===selected).map(m=>`<div class="bubble out">${esc(m.text)}<small>Simulated ${m.template?'approved template':'reply'} / not actually sent</small></div>`).join('')}</div>${blocked?notice('Do not contact','An opt-out blocks both manual messages and automated retries. No send action is available.','amber'):closed?notice('Use an approved template','The customer-service window is closed. Free-form sending is unavailable; choose a relevant approved template.','amber'):''}<div class="chat-compose"><label>Message<textarea id="chat-message" ${closed||blocked?'disabled':''} placeholder="Write a specific operational reply"></textarea></label>${btn('Simulate reply','chat-send',true,closed||blocked?'disabled':'')}${!blocked?btn('Choose template','template'):''}</div><p id="chat-error" class="error" role="alert"></p></div></section><div class="grid cols-2 spacer">${card('Operational reminder rules',table(['Trigger','Recipient check','State'],[['Onboarding incomplete','Opt-in + approved template',badge('Preview only','gray')],['Action awaiting client','Still pending + unexpired link',badge('Preview only','gray')],['Validation reminder','Deduplicate against prior send',badge('Preview only','gray')]]))}${card('Delivery and retry review',`<div class="line"><span>DEMO-MSG-003</span>${badge(state.delivery,state.delivery.startsWith('Failed')?'amber':'lilac')}</div><p class="subtle spacer">Retry only a temporary failure after rechecking eligibility. Do not retry opt-outs, successful sends or permanent failures.</p><div class="actions spacer">${btn('Review retry eligibility','retry')}</div>`+notice('No delivery guarantee','Queued, sent, delivered and read are separate states. None automatically confirms a financial transaction.'))}</div><p class="subtle spacer">Design guardrails follow the <a href="https://whatsappbusiness.com/policy/" target="_blank" rel="noopener noreferrer">WhatsApp Business Messaging Policy</a>: opt-in, opt-out handling and approved templates outside the 24-hour service window. Provider capabilities and template classification must be checked again before implementation.</p>`;}
const metricSets={rm:[['Business goal',80,40],['Client service',90,25],['Quality',86,15],['Peer behaviour',80,20]],ops:[['Weighted case completion',90,40],['Standard-time efficiency',85,30],['Quality review',95,20],['Peer behaviour',80,10]]};
function metrics(){return metricSets[state.scoreRole].map(([n,v,w])=>[n,state.period==='day'?Math.max(0,v-7):state.period==='closed'?Math.max(0,v-2):v,w]);}
function score(){return metrics().reduce((n,[,v,w])=>n+v*w/100,0);}
function performance(){const s=score(),needed=s*state.salary/50000;return head('PERFORMANCE / EXPLAINABLE SCORE','Know what counts. See what can improve.','Illustrative formulas and fictional employees. No actual salary or appraisal decision is being made.',`<label>Team model<select id="score-role"><option value="rm" ${state.scoreRole==='rm'?'selected':''}>Relationship manager</option><option value="ops" ${state.scoreRole==='ops'?'selected':''}>Operations</option></select></label><label>Period<select id="score-period"><option value="month" ${state.period==='month'?'selected':''}>September / current</option><option value="day" ${state.period==='day'?'selected':''}>5 September / daily</option><option value="closed" ${state.period==='closed'?'selected':''}>August / closed snapshot</option></select></label>`)+tabs(['performance','appraisals'])+
  `<div class="grid cols-3">${stat('Current scope',state.period==='day'?'5 Sep':state.period==='closed'?'August':'September','All factors use this same period')}${stat('Weighted score',s.toFixed(1)+' / 100','Example weighting, pending approval','accent')}${stat('Snapshot',state.period==='closed'?'Locked':'In progress',state.period==='closed'?'Later client remapping does not rewrite it':'Daily calculation preview','purple')}</div><div class="grid split spacer">${card(state.scoreRole==='rm'?'Relationship-manager score':'Operations score',metrics().map(([n,v,w])=>`<div class="metric"><div class="line"><strong>${n}</strong><span>${v}% achievement / ${w}% weight</span></div><div class="progress"><span style="width:${v}%"></span></div><small>${v} × ${w}% = ${(v*w/100).toFixed(1)} points</small></div>`).join('')+notice('A visible calculation, not a hidden rating','Example score = sum of achievement × weight. Operations uses its own task-mix model. The approved workbook must replace these illustrative inputs.')+btn('Review sample weights','weights'))}${card('Sample business ranking',table(['Employee','Score','Context'],[[state.scoreRole==='rm'?'Asha Demo':'Nikhil Demo',s.toFixed(1),badge('Selected')],['Demo colleague 2',(s-4.2).toFixed(1),'Same model'],['Demo colleague 3',(s-7.5).toFixed(1),'Same period']])+`<p class="subtle spacer">Visibility and ranking rules need your approval. Different role models should not be compared as if the same work was measured.</p>`+btn('Preview peer feedback','peer'))}</div><div class="grid cols-2 spacer">${card('Salary what-if / private self-view',`<p class="subtle">Sample current salary: ${money(50000)}. This is an illustration, not an increment offer.</p><label class="spacer">Desired monthly salary <strong id="salary-value">${money(state.salary)}</strong><input id="salary-range" type="range" min="50000" max="70000" step="1000" value="${state.salary}"></label><div class="scenario-panel spacer"><h3>Illustrative scenario</h3><p id="scenario-score">Target score: ${needed.toFixed(1)} / 100${needed>100?' / above this model’s ceiling':''}</p><p class="subtle spacer">Example only: current score × desired salary / current salary. The company’s salary policy and factor-improvement rules are still unconfirmed.</p></div>`)}${card('Review and protect the result',`<div class="line"><span>Source workbook</span>${badge('Awaiting reconciliation','amber')}</div><div class="line"><span>Peer-rating weight</span>${badge('Illustrative only','amber')}</div><div class="line"><span>Warning deductions</span>${badge('Not calculated','gray')}</div><div class="line"><span>Closed period edits</span><strong>Controlled correction required</strong></div><p class="subtle spacer">Changing weights should apply to an agreed future period. A closed-month snapshot is preserved even if clients are later reassigned.</p><div class="actions spacer">${link('Open appraisal cycle','appraisals',true)}</div>`)}</div>`;}
function appraisals(){return head('PERFORMANCE / APPRAISALS','A conversation, supported by evidence.','Self-review, manager discussion and a documented final decision. Salary changes remain a separate approval.',badge(state.appraisal,state.appraisal==='Finalized'?'':'lilac'))+tabs(['performance','appraisals'])+
  `<div class="grid split">${card('Asha Demo / September review',`<div class="reviewer">${avatar(people[0])}<div><h3>Monthly appraisal / sample cycle</h3><p class="subtle">Reviewer: Kiran Demo / Employee: Asha Demo</p></div></div><div class="stepper"><div class="done"><strong>01 Self-review</strong>Employee reflection</div><div class="${state.appraisal!=='Self-review draft'?'done':''}"><strong>02 Manager review</strong>Evidence + discussion</div><div class="${state.appraisal==='Finalized'?'done':''}"><strong>03 Finalized</strong>Snapshot retained</div></div><form id="appraisal-form" novalidate><label>Achievements and challenges<textarea name="reflection" ${state.appraisal!=='Self-review draft'?'readonly':''} placeholder="Record what went well and what support you need">${esc(state.selfText)}</textarea></label><label class="spacer">Next-period development goal<textarea name="goal" placeholder="A measurable goal agreed with the employee" ${state.appraisal==='Finalized'?'readonly':''}>${esc(state.goalText)}</textarea></label><label class="spacer">Manager discussion notes<textarea name="manager" ${state.role!=='senior'||state.appraisal==='Finalized'?'readonly':''} placeholder="Required before finalizing the mock review">${esc(state.managerText)}</textarea></label><p id="appraisal-error" class="error" role="alert"></p><div class="actions">${state.appraisal==='Self-review draft'&&state.role==='employee'?'<button class="primary" type="submit">Submit self-review</button>':''}${state.appraisal==='Manager review'&&state.role==='senior'?'<button class="primary" type="submit">Finalize mock appraisal</button>':''}</div></form>${state.appraisal==='Finalized'?notice('Mock appraisal finalized','The reviewed result is preserved. No compensation change or disciplinary action has been triggered.'):notice('Try both perspectives','Use Employee to submit the self-review, then Senior approver to complete the manager review.')}`)}${card('Evidence, not surprises',`<div class="score-ring"><strong>83.4</strong><span>illustrative current score</span></div><div class="line"><span>Business and service evidence</span>${badge('Sample')}</div><div class="line"><span>Peer feedback</span>${badge('Visibility to confirm','amber')}</div><div class="line"><span>Employee voice</span><strong>Included</strong></div><div class="line"><span>Period snapshot</span><strong>Preserved at finalization</strong></div><p class="subtle spacer">Agree the review frequency, eligible reviewers, peer-rating privacy and correction process. Do not use an unapproved score to change a real salary.</p>`)}</div>`;}
function controls(){return head('DAILY WORK / CONTROL POINTS','Better records. Safer edits.','A meaningful description is required for calls and meetings. Only a designated senior can propose a task revision.')+
  `<div class="grid cols-2">${card('Log a client activity',`<form id="activity-form" novalidate><div class="form-grid"><label>Activity type<select name="type"><option>Call</option><option>Meeting</option><option>Other activity</option></select></label><label>Client<select name="client"><option>Demo Client A</option><option>Demo Client B</option></select></label><label>Date<input name="date" type="date" value="2026-09-05"></label><label>Duration (minutes)<input name="duration" type="number" value="15" min="1" max="480"></label><label class="full">Description <span aria-hidden="true">*</span><textarea name="description" placeholder="What was discussed, the outcome and the next step"></textarea></label></div><p id="activity-error" class="error" role="alert"></p><button class="primary">Save mock activity</button></form><p class="subtle spacer">Blank or whitespace-only descriptions are rejected. Navigation is not trapped. No auto-filled generic description is used.</p>${state.activity.map(a=>`<div class="request"><strong>${esc(a.type)} / ${esc(a.client)}</strong><p>${esc(a.description)}</p><small>${a.duration} minutes / saved in this simulation</small></div>`).join('')}`)}${card('Task DEMO-1042 / edit control',`<div class="line"><span>Task</span><strong>New investment request</strong></div><div class="line"><span>Amount</span><strong id="task-amount">${money(state.taskAmount)}</strong></div><div class="line"><span>Instruction state</span>${badge('Not processed','lilac')}</div><div class="line"><span>Current revision</span><strong>${state.taskHistory.length+1}</strong></div>`+notice('Senior-only editing',state.role==='senior'?'You can propose an edit with a mandatory reason. A separate checker must approve it before the task changes.':'You can view this task. The edit action is reserved for designated senior roles.','amber')+`<div class="actions">${btn('Edit task','task-edit',true,state.role==='senior'?'':'disabled')}${btn('View processed-task example','processed-task')}</div>${state.taskPending?`<div class="scenario-panel spacer"><h3>Revision awaiting separate checker</h3><p>${money(state.taskAmount)} → ${money(state.taskPending.amount)}</p><p class="subtle">Reason: ${esc(state.taskPending.reason)}</p><p class="subtle">Original instructions remain unchanged.</p>${btn('Preview separate checker','task-check',false)}</div>`:''}<div class="spacer"><h3>Edit history</h3>${state.taskHistory.length?state.taskHistory.map(h=>`<div class="request"><strong>${money(h.from)} → ${money(h.to)}</strong><p>${esc(h.reason)}</p><small>Proposed: Kiran Demo / checked: Designated Checker Demo</small></div>`).join(''):'<p class="subtle spacer">No revisions yet. Original task retained.</p>'}</div>`)}</div>`;}
function videos(){const selected=location.hash.split('/')[1]||'payroll',m=modules.find(x=>x.id===selected)||modules[0];return head('REVIEW LIBRARY','Watch one module at a time.','Six short captioned walkthroughs. Each video shows the same interactive prototype you can explore here.')+`<div class="video-list">${modules.map(x=>link(x.number+' '+x.title,'videos/'+x.id,x.id===m.id)).join('')}</div><section class="card"><div class="card-head"><div><div class="eyebrow">${m.number} / MODULE WALKTHROUGH</div><h2>${m.title}</h2><p>${m.text}</p></div>${link('Open mock screens',m.id,true)}</div><video class="video-frame" controls playsinline preload="metadata" src="videos/${m.video}" aria-label="${m.title} walkthrough"><track kind="captions" src="videos/${m.video.replace('.mp4','.vtt')}" srclang="en" label="English"></video><p class="subtle spacer">Captioned, intentionally silent walkthrough. No production actions are performed.</p><div class="actions spacer"><a class="button" href="videos/${m.video}" download>Download video</a></div></section>`;}
const screens={home,payroll,attendance,leave,regularization,people:organization,profile,policies,whatsapp,performance,appraisals,controls,videos};
function render(){route=(location.hash.slice(1)||'home').split('/')[0];if(!screens[route])route='home';$('#main').innerHTML=screens[route]();$('#breadcrumb').textContent='Acornia / '+routes[route];$('#role-avatar').textContent=state.role==='hr'?'MD':state.role==='senior'?'KD':'AD';$('#nav').innerHTML=[['home','Overview','00'],['payroll','Payroll','01'],['attendance','Attendance & leave','02'],['people','Employee hub','03'],['whatsapp','WhatsApp','04'],['performance','Performance & appraisals','05'],['controls','Activity & task controls','06'],['videos','Walkthrough library','07']].map(([id,title,no])=>`<a href="#${id}" class="${route===id||groupFor(route).id===id?'active':''}" ${route===id?'aria-current="page"':''}><span class="nav-icon">${no}</span>${title}</a>`).join('');renderFeedback();}
function renderFeedback(){const m=route==='videos'?(modules.find(x=>x.id===location.hash.split('/')[1])||groupFor(route)):groupFor(route),key='acornia-people-mock-v1:'+m.id;let draft={};try{draft=JSON.parse(localStorage.getItem(key)||'{}');}catch{state.feedbackStorageError=true;}$('#feedback').innerHTML=`<div class="feedback-top"><div><div class="eyebrow">YOUR FEEDBACK / ${esc(m.title)}</div><h2 id="feedback-title">Does this match how you want to work?</h2></div><label>Review status<select id="feedback-decision"><option value="">Not reviewed</option><option value="looks-right">Looks right as a mock</option><option value="changes">Changes needed</option><option value="question">I have a question</option></select></label></div><p>${esc(m.question)}</p><div class="qfield" id="feedback-notes" data-q="${m.id}" contenteditable="true" role="textbox" aria-label="Feedback for ${esc(m.title)}" aria-multiline="true" data-placeholder="Write the changes you want here. Do not enter employee or client personal information."></div><p id="feedback-status">Device-only draft. Copy or download it and share it in the group, or submit it through private GitHub. This does not approve implementation.</p><div class="actions">${btn('Copy module feedback','feedback-copy')}${btn('Download feedback','feedback-download')}<a class="button" target="_blank" rel="noopener noreferrer" href="https://github.com/TranquilVedaPvtLtd/acornia-review-135-records/issues/new?title=${encodeURIComponent('[Mock review] '+m.title)}">Open private GitHub submission</a></div>`;$('#feedback-notes').textContent=draft.notes||'';$('#feedback-decision').value=draft.decision||'';$('#feedback').dataset.key=key;$('#feedback').dataset.module=m.title;}
function saveFeedback(){const notes=$('#feedback-notes').textContent,decision=$('#feedback-decision').value;try{localStorage.setItem($('#feedback').dataset.key,JSON.stringify({notes,decision,version:1,updated:new Date().toISOString()}));$('#feedback-status').textContent='Draft stored on this device only. Copy or download and share to submit. No private submission is verified here.';}catch{$('#feedback-status').textContent='Device storage unavailable. Copy or download your feedback before leaving.';}}
function feedbackText(){return `Acornia prototype review / version 1\nModule: ${$('#feedback').dataset.module}\nDecision: ${$('#feedback-decision').value||'Not reviewed'}\n\n${$('#feedback-notes').textContent||'(No comment)'}\n\nMock-screen feedback only. This does not authorize implementation or production deployment.`;}
function salaryDialog(id){const p=people.find(x=>x.id===id)||people[0];if(state.role==='employee'&&id!=='asha')return;dialog(p.name+' / salary breakdown',`<p class="subtle">August 2026 / entirely fictional amounts. No statutory rates assumed.</p>`+moneyLine('Basic salary',p.gross*.5)+moneyLine('House rent allowance',p.gross*.3)+moneyLine('Other allowance',p.gross*.2)+moneyLine('Gross salary',p.gross,true)+moneyLine('Illustrative deductions',p.deductions)+moneyLine('Net pay',p.gross-p.deductions,true));}
function action(a,id){switch(a){
case 'close':closeDialog();break;
case 'salary':salaryDialog(id);break;
case 'payroll-submit':if(state.role==='hr'&&state.payroll==='Draft'){state.payroll='In review';render();showToast('Mock run submitted. A separate senior can now review it.');}break;
case 'payroll-finalize':if(state.role==='senior'&&state.payroll==='In review'){state.payroll='Finalized';render();showToast('Mock payroll finalized. No payment made.');}break;
case 'payroll-return':if(state.role==='senior'){state.payroll='Draft';render();showToast('Mock payroll returned to HR for correction.');}break;
case 'payslip':dialog('Sample payslip / Asha Demo',`<div class="sample-document"><strong>SAMPLE ONLY / NOT VALID FOR USE</strong><h3>Acornia / August 2026</h3><p>Asha Demo / DEMO-ASHA</p>${moneyLine('Gross salary',50000)}${moneyLine('Deductions',3200)}${moneyLine('Net salary',46800,true)}</div><p class="subtle">The real PDF format and employer details require approval. This preview is not an issued payslip.</p>`);break;
case 'payslip-download':download('sample-payslip-NOT-VALID.txt','SAMPLE ONLY / NOT AN ISSUED PAYSLIP\nAsha Demo / August 2026\nGross: Rs 50,000\nIllustrative deductions: Rs 3,200\nNet: Rs 46,800');break;
case 'month-prev':case 'month-next':{const d=new Date(Date.UTC(state.year,state.month+(a==='month-next'?1:-1),1));state.year=d.getUTCFullYear();state.month=d.getUTCMonth();state.day=1;render();break;}
case 'day':state.day=Number(id);render();break;
case 'checkin':dialog('Preview photo check-in',`<div class="sample-document"><span class="avatar large" style="margin:auto">AD</span><p>Sample photo placeholder</p><strong>NO CAMERA IS ACCESSED</strong></div><label>Source<select id="checkin-source"><option>Laptop / office</option><option>Mobile / field work</option></select></label><p class="subtle spacer">Location permissions and field-work eligibility need company approval. This records no real attendance.</p><div class="actions spacer">${btn('Record mock check-in','checkin-record',true)}</div>`);break;
case 'checkin-record':state.checkinSource=$('#checkin-source').value;state.checkedIn=true;closeDialog();render();showToast('Mock check-in recorded. Login and attendance remain separate.');break;
case 'leave-approve':case 'leave-reject':if(state.role==='senior'){const r=state.leave.find(x=>x.id===Number(id));if(r&&r.status==='Pending')r.status=a==='leave-approve'?'Approved':'Rejected';render();}break;
case 'correction-approve':case 'correction-reject':if(state.role==='senior'){const r=state.corrections.find(x=>x.id===Number(id));if(r&&r.status==='Pending'){if(a==='correction-approve'&&r.kind==='leave'){const available=(r.leaveType==='Casual leave'?6:9)-leaveUsed(r.leaveType);if(available<1){showToast('Insufficient sample leave balance.');break;}state.leave.push({id:Date.now(),from:r.date,to:r.date,type:r.leaveType,duration:'full',reason:r.reason,status:'Approved'});}r.status=a==='correction-approve'?'Approved':'Rejected';}render();showToast('Mock decision recorded. The calendar reflects approved corrections.');}break;
case 'profile':state.profile=id;location.hash='profile';break;
case 'document':dialog('Sample '+esc(id),`<div class="sample-document"><strong>FICTIONAL PLACEHOLDER</strong><h3>${esc(id)}</h3><p>Demo employee document</p><p>Identifier: DEMO / NOT A VALID DOCUMENT</p></div><p class="subtle">A real document would require authenticated, audited access. No real personnel file is present in this prototype.</p>`);break;
case 'document-update':state.docs[state.profile+id]=true;render();showToast('Sample document updated. No file was uploaded.');break;
case 'policy-view':dialog(esc(id)+' / '+state.policyYear,`<div class="sample-document"><strong>SAMPLE POLICY / NOT COMPANY RULES</strong><p>${esc(id)} / ${state.policyYear}</p></div><h3>Items to confirm</h3><p class="subtle spacer">The company-approved PDF, effective date, eligible employees, policy owner, version history and acknowledgement process.</p><div class="actions spacer">${btn('Download sample outline','policy-download',false,`data-id="${esc(id)}"`)}</div>`);break;
case 'policy-download':download('sample-policy-outline.txt',`SAMPLE ONLY / NOT COMPANY POLICY\n${id} / ${state.policyYear}\nProvide the approved PDF, effective date, policy owner and access rules.`);break;
case 'policy-ack':state.ack[id+state.policyYear]=true;render();showToast('Sample acknowledgement recorded in this session only.');break;
case 'policy-publish':dialog('Publish a policy / proposed HR flow',`<div class="form-grid"><label>Policy title<input value="Attendance and leave"></label><label>Effective year<input value="2026" readonly></label><label class="full">Version note<textarea>Example revised policy for review.</textarea></label></div>`+notice('No real upload here','In the proposed product, HR uploads a PDF, sets the effective date and retains earlier versions.')+btn('Preview new version','policy-version',true));break;
case 'policy-version':closeDialog();showToast('Publishing flow previewed. No policy was uploaded or replaced.');break;
case 'chat-select':state.chat=id;render();break;
case 'chat-send':if(state.chat==='open'){const text=$('#chat-message').value.trim();if(!text){$('#chat-error').textContent='Enter a message before simulating a reply.';break;}state.messages.push({chat:state.chat,text,template:false});render();showToast('Simulated reply only. Nothing sent to WhatsApp.');}break;
case 'template':if(state.chat!=='optout')dialog('Choose an operational template',`<div class="request"><strong>onboarding_status / English</strong>${badge('Mock approved template')}<p>Hello, your onboarding request is being reviewed. We will update you when the next step is ready.</p></div><p class="subtle">Provider approval, category and variables must be validated for the real template. No financial or identity details are included.</p><div class="actions spacer">${btn('Simulate template message','template-send',true)}</div>`);break;
case 'template-send':if(state.chat!=='optout'){state.messages.push({chat:state.chat,text:'Hello, your onboarding request is being reviewed. We will update you when the next step is ready.',template:true});closeDialog();render();showToast('Template simulated. No message sent.');}break;
case 'retry':dialog('Retry eligibility / DEMO-MSG-003',`<div class="line"><span>Recipient</span><strong>Demo Client A</strong></div><div class="line"><span>Failure type</span>${badge('Temporary connection','amber')}</div><div class="line"><span>Opt-in still valid</span>${badge('Yes / sample')}</div><div class="line"><span>Already delivered</span>${badge('No / sample')}</div><div class="line"><span>Attempt limit and expiry</span>${badge('Within sample policy')}</div>`+notice('A reviewed retry, not a blanket resend','A production retry must recheck provider guidance, stop conditions, consent and deduplication.')+btn('Queue mock retry','retry-confirm',true,state.delivery.startsWith('Queued')?'disabled':''));break;
case 'retry-confirm':state.delivery='Queued for reviewed retry';closeDialog();render();showToast('Mock retry queued once. No external message sent.');break;
case 'weights':dialog('Sample scoring model / not approved',`<div class="score-config">${metricSets[state.scoreRole].map(([n,,w],i)=>`<label>${n}<input name="weight-${i}" type="number" min="0" max="100" value="${w}" readonly></label>`).join('')}</div>`+notice('Company workbook still required','The displayed weights total 100%. Real configuration needs effective dates, authorized edits and closed-period protection. This preview does not change the formula.')+`<p class="subtle">Warning deductions are intentionally not calculated because the rule is unresolved.</p>`);break;
case 'peer':dialog('Peer feedback / sample form',`<p class="subtle">Eligible raters, anonymity, visibility and weights must be agreed before collecting real feedback.</p><form id="peer-form" novalidate><div class="score-config spacer">${['Cooperation','Responsiveness','Quality of handoff'].map((n,i)=>`<label>${n}<select name="rating-${i}"><option value="">Choose</option>${[1,2,3,4,5].map(x=>`<option>${x}</option>`).join('')}</select></label>`).join('')}</div><label class="spacer">Example or context<textarea name="reason" placeholder="Give specific, work-related feedback"></textarea></label><p id="peer-error" class="error" role="alert"></p><button class="primary">Save sample peer feedback</button></form>`);break;
case 'task-edit':if(state.role==='senior'&&!state.taskPending)dialog('Propose a task revision',`<form id="task-form" novalidate><label>Investment amount<input name="amount" type="number" min="1" value="${state.taskAmount}"></label><label class="spacer">Reason for change <span aria-hidden="true">*</span><textarea name="reason" placeholder="Explain why the original task needs changing"></textarea></label><p id="task-error" class="error" role="alert"></p><button class="primary">Submit mock revision</button></form>`+notice('Original task remains intact','A separate checker reviews the change. No financial order is amended by this prototype.'));else if(state.taskPending)showToast('A revision is already awaiting review.');break;
case 'task-check':if(state.role==='senior'&&state.taskPending)dialog('Separate-checker preview',`<p class="subtle">Previewing Designated Checker Demo, a different authorized person. This is a simulation of the approval boundary.</p><div class="line"><span>Before</span><strong>${money(state.taskAmount)}</strong></div><div class="line"><span>Proposed</span><strong>${money(state.taskPending.amount)}</strong></div><p class="spacer">${esc(state.taskPending.reason)}</p><div class="actions spacer">${btn('Simulate checker approval','task-check-confirm',true)}</div>`);break;
case 'task-check-confirm':if(state.role==='senior'&&state.taskPending){state.taskHistory.push({from:state.taskAmount,to:state.taskPending.amount,reason:state.taskPending.reason});state.taskAmount=state.taskPending.amount;state.taskPending=null;closeDialog();render();showToast('Mock revision accepted. Original amount and reason remain in history.');}break;
case 'processed-task':dialog('Processed instructions are locked',notice('Do not rewrite an executed instruction','Task DEMO-1043 has already been processed. Even a senior uses a separate amendment/correction process; the original transaction is not edited.','amber')+btn('Edit processed task','',false,'disabled'));break;
case 'feedback-copy':navigator.clipboard.writeText(feedbackText()).then(()=>showToast('Feedback copied. Share it in the group or paste and submit on private GitHub.')).catch(()=>{download('module-feedback.txt',feedbackText());showToast('Clipboard unavailable. Feedback downloaded instead.');});break;
case 'feedback-download':download('acornia-module-feedback.txt',feedbackText());break;
}}
document.addEventListener('click',e=>{const target=e.target.closest('[data-action]');if(target&&!target.disabled)action(target.dataset.action,target.dataset.id);});
document.addEventListener('change',e=>{if(e.target.id==='role'){state.role=e.target.value;render();}if(e.target.id==='score-role'){state.scoreRole=e.target.value;render();}if(e.target.id==='score-period'){state.period=e.target.value;render();}if(e.target.id==='policy-year'){state.policyYear=e.target.value;render();}if(e.target.id==='feedback-decision')saveFeedback();if(e.target.id==='correction-kind'){const leave=e.target.value==='leave';$('#correction-leave-label').hidden=!leave;document.querySelectorAll('#correction-form input[type=time]').forEach(x=>x.disabled=leave);}});
document.addEventListener('input',e=>{if(e.target.id==='feedback-notes')saveFeedback();if(e.target.id==='salary-range'){state.salary=Number(e.target.value);$('#salary-value').textContent=money(state.salary);const n=score()*state.salary/50000;$('#scenario-score').textContent=`Target score: ${n.toFixed(1)} / 100${n>100?' / above this model’s ceiling':''}`;}if(e.target.name==='reflection')state.selfText=e.target.value;});
document.addEventListener('submit',e=>{e.preventDefault();const form=e.target,d=Object.fromEntries(new FormData(form));
 if(form.id==='leave-form'){if(!d.from||!d.to||d.to<d.from||!d.reason.trim()){$('#leave-error').textContent='Choose a valid date range and provide a reason.';return;}if(d.type==='Casual leave'&&d.duration==='half'){$('#leave-error').textContent='This sample policy permits casual leave in full days only. Confirm the company rule.';return;}if(d.duration==='half'&&d.from!==d.to){$('#leave-error').textContent='Choose a single date for a half-day request.';return;}const requested=d.duration==='half'?.5:Math.round((Date.parse(d.to)-Date.parse(d.from))/86400000)+1;const available=(d.type==='Casual leave'?6:9)-leaveUsed(d.type);if(requested>available){$('#leave-error').textContent='This request exceeds the sample leave balance.';return;}if(state.leave.some(r=>r.status!=='Rejected'&&d.from<=r.to&&d.to>=r.from)){$('#leave-error').textContent='A leave request already overlaps these dates.';return;}state.leave.push({...d,id:Date.now(),status:'Pending'});render();showToast('Mock leave request submitted. Balance is unchanged until approval.');}
 if(form.id==='correction-form'){if(!d.date||(d.kind!=='leave'&&(!d.from||!d.to||d.to<=d.from))||!d.reason.trim()){$('#correction-error').textContent='Provide a date, an end time after the start time and a meaningful reason.';return;}if(d.date<'2026-09-01'){$('#correction-error').textContent='August is closed in this mock. A separate payroll adjustment must be reviewed.';return;}if(d.date>'2026-09-05'){$('#correction-error').textContent='Attendance corrections cannot be submitted for a future day in this mock.';return;}if(state.corrections.some(r=>r.date===d.date&&r.status!=='Rejected')){$('#correction-error').textContent='A correction already exists for this date.';return;}state.corrections.push({...d,id:Date.now(),status:'Pending'});render();showToast('Mock correction submitted for senior review.');}
 if(form.id==='activity-form'){if(!d.description.trim()){$('#activity-error').textContent='Description is required. Record the discussion, outcome and next step.';return;}if(!d.date||!Number.isFinite(+d.duration)||+d.duration<=0||+d.duration>480){$('#activity-error').textContent='Choose a date and duration between 1 and 480 minutes.';return;}state.activity.push({...d,description:d.description.trim()});render();showToast('Mock activity saved with its description.');}
 if(form.id==='task-form'){if(state.role!=='senior')return;if(!d.reason.trim()||!Number.isFinite(+d.amount)||+d.amount<=0||+d.amount===state.taskAmount){$('#task-error').textContent='Enter a changed positive amount and a reason.';return;}state.taskPending={amount:+d.amount,reason:d.reason.trim()};closeDialog();render();showToast('Mock revision awaiting a separate checker.');}
 if(form.id==='appraisal-form'){if(state.appraisal==='Self-review draft'&&state.role==='employee'){if(!d.reflection.trim()||!d.goal.trim()){$('#appraisal-error').textContent='Add a reflection and development goal before submitting.';return;}state.selfText=d.reflection;state.goalText=d.goal;state.appraisal='Manager review';render();}else if(state.appraisal==='Manager review'&&state.role==='senior'){if(!d.manager.trim()||!d.goal.trim()){$('#appraisal-error').textContent='Document the manager discussion and agreed goal before finalizing.';return;}state.managerText=d.manager;state.goalText=d.goal;state.appraisal='Finalized';render();showToast('Mock appraisal finalized. No salary changed.');}}
 if(form.id==='peer-form'){if([0,1,2].some(i=>!d['rating-'+i])||!d.reason.trim()){$('#peer-error').textContent='Choose all three ratings and add specific context.';return;}closeDialog();showToast('Sample peer feedback recorded for this walkthrough only.');}
});
window.addEventListener('hashchange',()=>{render();window.scrollTo({top:0,behavior:'instant'});});
render();
